import{_ as e,o as n,c as s,ag as t}from"./chunks/framework.1IVNT0ce.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"installation.md","filePath":"installation.md"}'),l={name:"installation.md"};function o(i,a,p,r,c,d){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Klix is a normal Python package with a small runtime dependency set:</p><ul><li><code>prompt_toolkit</code></li><li><code>rich</code></li><li><code>pydantic</code></li></ul><p>See also <a href="./getting-started">Getting Started</a> and <a href="./quickstart">Quickstart</a>.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Python 3.9+</li><li>A terminal with standard input/output for interactive use</li></ul><h2 id="install-from-the-repository" tabindex="-1">Install From The Repository <a class="header-anchor" href="#install-from-the-repository" aria-label="Permalink to &quot;Install From The Repository&quot;">​</a></h2><p>For local development:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">git</span><span style="color:#C3E88D;"> clone</span><span style="color:#89DDFF;"> &lt;</span><span style="color:#C3E88D;">repo-ur</span><span style="color:#BABED8;">l</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#82AAFF;">cd</span><span style="color:#C3E88D;"> klix</span></span>
<span class="line"><span style="color:#FFCB6B;">python</span><span style="color:#C3E88D;"> -m</span><span style="color:#C3E88D;"> venv</span><span style="color:#C3E88D;"> .venv</span></span>
<span class="line"><span style="color:#82AAFF;">source</span><span style="color:#C3E88D;"> .venv/bin/activate</span></span>
<span class="line"><span style="color:#FFCB6B;">pip</span><span style="color:#C3E88D;"> install</span><span style="color:#C3E88D;"> -e</span><span style="color:#C3E88D;"> .</span></span></code></pre></div><p>That gives you:</p><ul><li>the <code>klix</code> Python package</li><li>the <code>klix</code> scaffold command</li></ul><h2 id="verify-the-install" tabindex="-1">Verify The Install <a class="header-anchor" href="#verify-the-install" aria-label="Permalink to &quot;Verify The Install&quot;">​</a></h2><p>Run:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">klix</span></span></code></pre></div><p>You should see:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>Usage: klix init &lt;name&gt;</span></span></code></pre></div><p>Then generate a starter app:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">klix</span><span style="color:#C3E88D;"> init</span><span style="color:#C3E88D;"> mytool</span></span>
<span class="line"><span style="color:#82AAFF;">cd</span><span style="color:#C3E88D;"> mytool</span></span>
<span class="line"><span style="color:#FFCB6B;">pip</span><span style="color:#C3E88D;"> install</span><span style="color:#C3E88D;"> -e</span><span style="color:#C3E88D;"> .</span></span>
<span class="line"><span style="color:#FFCB6B;">mytool</span></span></code></pre></div><p>See <a href="./quickstart">Quickstart</a> for the next step.</p><h2 id="installing-in-a-clean-environment" tabindex="-1">Installing In A Clean Environment <a class="header-anchor" href="#installing-in-a-clean-environment" aria-label="Permalink to &quot;Installing In A Clean Environment&quot;">​</a></h2><p>If you want to verify the full install path from scratch:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">python</span><span style="color:#C3E88D;"> -m</span><span style="color:#C3E88D;"> venv</span><span style="color:#C3E88D;"> /tmp/klix-venv</span></span>
<span class="line"><span style="color:#82AAFF;">source</span><span style="color:#C3E88D;"> /tmp/klix-venv/bin/activate</span></span>
<span class="line"><span style="color:#FFCB6B;">pip</span><span style="color:#C3E88D;"> install</span><span style="color:#C3E88D;"> -e</span><span style="color:#C3E88D;"> /path/to/klix</span></span>
<span class="line"><span style="color:#FFCB6B;">klix</span><span style="color:#C3E88D;"> init</span><span style="color:#C3E88D;"> demo</span></span></code></pre></div><p>This is useful when you are changing packaging metadata. See <a href="./contributing">Contributing</a>.</p><h2 id="what-gets-installed" tabindex="-1">What Gets Installed <a class="header-anchor" href="#what-gets-installed" aria-label="Permalink to &quot;What Gets Installed&quot;">​</a></h2><p>The package includes:</p><ul><li>the top-level framework package <code>klix</code></li><li>subpackages for input, output, layout, and CLI tooling</li><li>the <code>klix</code> console entry point defined in <code>pyproject.toml</code></li></ul><p>The implementation currently packages framework code, not documentation or examples as runtime dependencies.</p><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><h3 id="running-without-editable-install" tabindex="-1">Running without editable install <a class="header-anchor" href="#running-without-editable-install" aria-label="Permalink to &quot;Running without editable install&quot;">​</a></h3><p>If you are working from the repo and examples cannot import <code>klix</code>, make sure you ran:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">pip</span><span style="color:#C3E88D;"> install</span><span style="color:#C3E88D;"> -e</span><span style="color:#C3E88D;"> .</span></span></code></pre></div><h3 id="using-a-non-interactive-environment-for-interactive-demos" tabindex="-1">Using a non-interactive environment for interactive demos <a class="header-anchor" href="#using-a-non-interactive-environment-for-interactive-demos" aria-label="Permalink to &quot;Using a non-interactive environment for interactive demos&quot;">​</a></h3><p>Some examples depend on prompt-driven interaction. If you pipe input or run inside CI, Klix will fall back to simpler stdin behavior. That is useful for tests, but selector dialogs and richer interactions are best tried in a real terminal. See <a href="./components/input">Input Components</a>.</p><h3 id="expecting-pip-install-klix-from-pypi-here" tabindex="-1">Expecting <code>pip install klix</code> from PyPI here <a class="header-anchor" href="#expecting-pip-install-klix-from-pypi-here" aria-label="Permalink to &quot;Expecting \`pip install klix\` from PyPI here&quot;">​</a></h3><p>This repository is the source tree. The docs in this folder describe the current repo state, not a separately published release pipeline.</p>`,35)])])}const m=e(l,[["render",o]]);export{u as __pageData,m as default};
